def write_page(slug,title,body,description=''):
 html=f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(description or title)}"><title>{e(title)} | STRUGAL Maroc</title><link rel="stylesheet" href="style.css"></head><body>{header}<main id="main" tabindex="-1">{body}</main>{footer}<script src="script.js"></script></body></html>'
 (dist/(slug+'.html')).write_text(html)
def crumb(label):return f'<nav class="breadcrumb wrap" aria-label="Fil d’Ariane"><a href="index.html">Accueil</a><span aria-hidden="true">/</span><span aria-current="page">{e(label)}</span></nav>'
def source_note(path):return '<p class="source-note">Informations issues de la documentation STRUGAL. '+ext(official(path),'Consulter la source officielle','inline-source')+'</p>'
def model_card(m):
 return f'''<article class="model-card" data-family="{m['kind']}"><a href="systeme-{m['slug']}.html" class="model-primary"><div class="model-image"><img src="assets/{m['img']}" alt="Coupe du système aluminium STRUGAL {m['name']}" loading="lazy"><span>{m['kind']}</span></div><div class="model-caption"><div><span>STRUGAL</span><h3>{m['name']}</h3></div><b aria-hidden="true">↗</b></div><p class="model-benefit">{m['short']}</p><dl class="card-specs"><div><dt>{m['facts'][0][0]}</dt><dd>{m['facts'][0][1]}</dd></div><div><dt>{m['facts'][1][0]}</dt><dd>{m['facts'][1][1]}</dd></div></dl><span class="model-cta">Voir les caractéristiques →</span></a></article>'''
for m in models:
 facts=''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in m['facts']);features=''.join('<li>'+e(f)+'</li>' for f in m['features'])
 body=crumb(m['name'])+f'''<section class="detail-hero wrap"><div class="detail-product-image"><img src="assets/{m['img']}" alt="Coupe technique du système STRUGAL {m['name']}"></div><div><p class="eyebrow dark">MENUISERIE ALUMINIUM / {m['kind'].upper()}</p><h1>{m['name']}</h1><p class="detail-lead">{m['short']}</p><p>{m['use']}</p><dl class="spec-grid">{facts}</dl>{button('contact.html?systeme='+m['slug'],'Étudier ce système pour mon projet')}</div></section><section class="detail-body wrap"><div><h2>Ce qui le distingue</h2><ul class="detail-list">{features}</ul><p class="technical-note">Les limites dépendent de la version, du vitrage et des dimensions. *Valeurs maximales selon configuration. Faites valider votre choix par le bureau technique.</p>{source_note(m['source'])}</div><aside class="resource-box"><h2>Documents techniques</h2><p>Dimensions, configurations et données de performance du fabricant.</p>{ext(official(m['pdf']),'Ouvrir la fiche technique PDF','button outline')}{button('service-bim.html','Trouver les ressources BIM')}<a class="text-link" href="service-conseil-technique.html">Demander un avis technique <span>→</span></a></aside></section><section class="related-section wrap"><h2>Comparer les autres systèmes {m['kind'].lower()}s</h2><div class="model-grid">{''.join(model_card(x) for x in models if x['kind']==m['kind'] and x!=m)}</div></section>'''
 write_page('systeme-'+m['slug'],m['name'],body,m['short'])
for slug,title,group,icon,path,intro,steps,related in families:
 cards=''.join(model_card(m) for m in models if m['slug'] in related)
